以下 C++程式實現部分 Map 的功能，keys 存字元，values 存該字元對應之整數值。01020304050607080910111213141516171819202122232425262728293031323334353637383940#include <iostream>#include <string>using namespace std;class IMap{public:IMap(int s) {mSize = 0;keys = new char[s];values = new int[s];for (int i=0; i<s; i++) { keys[i]='\0'; values[i]=0; }}int &operator[] (char c) {for (int i=0; i<mSize; i++) if (keys[i]==c) return values[i];keys[mSize]=c;return values[mSize++];}~IMap() { delete keys; delete values; }private:char *keys;int *values;int mSize;};void test01() {IMap x(10);x['a'] = 5;cout<<x['a']<<endl;cout<<x['b']<<endl;}int countChar(string s, char c) {IMap x(20);for (int i=0; i<s.length();i++)x[s[i]] = (a) ;return(b) ;}void test02() { cout<<countChar("ababbccdewbsu", 'b')<<endl; }int main() {test01();test02();return 0;}
①請說明執行 test01()的輸出；以及說明 IMap 類別 int &operator[] (char c)函式的設計邏輯。(15 分)
②函式 countChar(s, c)是利用 IMap 類別的 Map 功能，統計在字串 s 中，字元 c 出現次數；請完成此函式(a), (b)使之能正常執行其功能。(10 分)以下 Java 程式模擬銀行帳戶存款與查詢餘額的多執行緒功能。Account是帳戶類別，可以存款與查詢餘額；ATM 類別可以操作帳戶的存款功能；Test 類別輸出查詢之最後帳戶餘額。01020304050607080910111213141516171819202122232425262728293031import java.util.ArrayList;class Account {public void deposit(int m) { balance = balance + m; }public int getBalance() { return balance; }private int balance=0;}class ATM extends Thread {public ATM(Account a, int m) {account = a; money = m;}public void run() {try {Thread.sleep(100);} catch (InterruptedException e) { e.printStackTrace(); }synchronized(Account.class) { account.deposit(money);}//account.deposit(money);}private Account account;private int money;}public class Test {public static void main(String[] args) throws InterruptedException {ArrayList<Thread> ts = new ArrayList<>();Account account = new Account();for(int i = 1 ; i <= 10 ; i++) {Thread atm = new ATM(account, i);atm.start();ts.add(atm);}for(Thread t : ts) { t.join(); }System.out.println("" + account.getBalance());}}
①請說明此程式的執行緒之特性以及此程式輸出。（10 分）
②將 Line 28 註解掉後，請說明程式執行結果與其運作原因。再將 Line 13註解掉，並打開 Line 14, 28 註解後，請說明此時程式執行結果與其運作原因。（15 分）
